            public ErrorMask Combine(ErrorMask? rhs)
            {
                if (rhs == null) return this;
                var ret = new ErrorMask();
                ret.EDID = this.EDID.Combine(rhs.EDID);
                ret.FULL = this.FULL.Combine(rhs.FULL);
                ret.LightingTemplate = this.LightingTemplate.Combine(rhs.LightingTemplate);
                ret.EncounterZone = this.EncounterZone.Combine(rhs.EncounterZone);
                ret.Location = this.Location.Combine(rhs.Location);
                ret.ParentWorldspace = this.ParentWorldspace.Combine(rhs.ParentWorldspace);
                ret.PNAM = this.PNAM.Combine(rhs.PNAM);
                ret.Climate = this.Climate.Combine(rhs.Climate);
                ret.Water = this.Water.Combine(rhs.Water);
                ret.LODWater = this.LODWater.Combine(rhs.LODWater);
                ret.NAM4 = this.NAM4.Combine(rhs.NAM4);
                ret.ICON = this.ICON.Combine(rhs.ICON);
                ret.Model = this.Model.Combine(rhs.Model, (l, r) => l.Combine(r));
                ret.NAMA = this.NAMA.Combine(rhs.NAMA);
                ret.Flags = this.Flags.Combine(rhs.Flags);
                ret.OrderedLandsTextures = new MaskItem<Exception?, IEnumerable<(int Index, Exception Value)>?>(Noggog.ExceptionExt.Combine(this.OrderedLandsTextures?.Overall, rhs.OrderedLandsTextures?.Overall), Noggog.ExceptionExt.Combine(this.OrderedLandsTextures?.Specific, rhs.OrderedLandsTextures?.Specific));
                ret.LNAM2 = this.LNAM2.Combine(rhs.LNAM2);
                ret.NAM5 = this.NAM5.Combine(rhs.NAM5);
                ret.Music = this.Music.Combine(rhs.Music);
                ret.NNAM = this.NNAM.Combine(rhs.NNAM);
                ret.XWEM = this.XWEM.Combine(rhs.XWEM);
                ret.TNAM = this.TNAM.Combine(rhs.TNAM);
                ret.UNAM = this.UNAM.Combine(rhs.UNAM);
                ret.XCLW = this.XCLW.Combine(rhs.XCLW);
                ret.WHGT = this.WHGT.Combine(rhs.WHGT);
                ret.WLEV = this.WLEV.Combine(rhs.WLEV);
                ret.CLSZ2 = this.CLSZ2.Combine(rhs.CLSZ2);
                ret.DNAM2 = this.DNAM2.Combine(rhs.DNAM2);
                ret.MHDT2 = this.MHDT2.Combine(rhs.MHDT2);
                ret.MNAM2 = this.MNAM2.Combine(rhs.MNAM2);
                ret.NAM0 = this.NAM0.Combine(rhs.NAM0);
                ret.NAM6 = this.NAM6.Combine(rhs.NAM6);
                ret.NAM9 = this.NAM9.Combine(rhs.NAM9);
                ret.ONAM2 = this.ONAM2.Combine(rhs.ONAM2);
                ret.RNAM2 = this.RNAM2.Combine(rhs.RNAM2);
                ret.VISI2 = this.VISI2.Combine(rhs.VISI2);
                ret.WCTR = this.WCTR.Combine(rhs.WCTR);
                ret.OffsetData = this.OffsetData.Combine(rhs.OffsetData);
                ret.TopCell = this.TopCell.Combine(rhs.TopCell, (l, r) => l.Combine(r));
                ret.SubCellsTimestamp = this.SubCellsTimestamp.Combine(rhs.SubCellsTimestamp);
                ret.SubCellsUnknown = this.SubCellsUnknown.Combine(rhs.SubCellsUnknown);
                ret.SubCells = new MaskItem<Exception?, IEnumerable<MaskItem<Exception?, WorldspaceBlock.ErrorMask?>>?>(Noggog.ExceptionExt.Combine(this.SubCells?.Overall, rhs.SubCells?.Overall), Noggog.ExceptionExt.Combine(this.SubCells?.Specific, rhs.SubCells?.Specific));
                return ret;
            }
            public static ErrorMask? Combine(ErrorMask? lhs, ErrorMask? rhs)
            {
                if (lhs != null && rhs != null) return lhs.Combine(rhs);
                return lhs ?? rhs;
            }
