                case "MajorRecord":
                case "IFallout76MajorRecord":
                case "Fallout76MajorRecord":
                case "IMajorRecordGetter":
                case "IFallout76MajorRecordGetter":
                    if (!Worldspace_Registration.SetterType.IsAssignableFrom(obj.GetType())) return;
                    this.Remove(obj, keys);
                    break;
                case "Cell":
                case "ICellGetter":
                case "ICell":
                case "ICellInternal":
                    {
                        if (obj.TopCell is {} TopCellitem)
                        {
                            TopCellitem.Remove(keys, type, throwIfUnknown);
