        public void FillEqualsMask(
            IWorldspaceGetter item,
            IWorldspaceGetter rhs,
            Worldspace.Mask<bool> ret,
            EqualsMaskHelper.Include include = EqualsMaskHelper.Include.All)
        {
            ret.EDID = string.Equals(item.EDID, rhs.EDID);
            ret.FULL = object.Equals(item.FULL, rhs.FULL);
            ret.LightingTemplate = item.LightingTemplate.Equals(rhs.LightingTemplate);
            ret.EncounterZone = item.EncounterZone.Equals(rhs.EncounterZone);
            ret.Location = item.Location.Equals(rhs.Location);
            ret.ParentWorldspace = item.ParentWorldspace.Equals(rhs.ParentWorldspace);
            ret.PNAM = item.PNAM == rhs.PNAM;
            ret.Climate = item.Climate.Equals(rhs.Climate);
            ret.Water = item.Water.Equals(rhs.Water);
            ret.LODWater = item.LODWater.Equals(rhs.LODWater);
            ret.NAM4 = item.NAM4.EqualsWithin(rhs.NAM4);
            ret.ICON = string.Equals(item.ICON, rhs.ICON);
            ret.Model = EqualsMaskHelper.EqualsHelper(
                item.Model,
                rhs.Model,
                (loqLhs, loqRhs, incl) => loqLhs.GetEqualsMask(loqRhs, incl),
                include);
            ret.NAMA = item.NAMA.EqualsWithin(rhs.NAMA);
            ret.Flags = item.Flags == rhs.Flags;
            ret.OrderedLandsTextures = item.OrderedLandsTextures.CollectionEqualsHelper(
                rhs.OrderedLandsTextures,
                (l, r) => object.Equals(l, r),
                include);
            ret.LNAM2 = MemorySliceExt.SequenceEqual(item.LNAM2, rhs.LNAM2);
            ret.NAM5 = string.Equals(item.NAM5, rhs.NAM5);
            ret.Music = item.Music.Equals(rhs.Music);
