        #region Mutagen
        public IEnumerable<IFormLinkGetter> EnumerateFormLinks(IWorldspaceGetter obj, bool iterateNestedRecords = true)
        {
            foreach (var item in base.EnumerateFormLinks(obj, iterateNestedRecords))
            {
                yield return item;
            }
            if (FormLinkInformation.TryFactory(obj.LightingTemplate, out var LightingTemplateInfo))
            {
                yield return LightingTemplateInfo;
            }
            if (FormLinkInformation.TryFactory(obj.EncounterZone, out var EncounterZoneInfo))
            {
                yield return EncounterZoneInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Location, out var LocationInfo))
            {
                yield return LocationInfo;
            }
            if (FormLinkInformation.TryFactory(obj.ParentWorldspace, out var ParentWorldspaceInfo))
            {
                yield return ParentWorldspaceInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Climate, out var ClimateInfo))
            {
                yield return ClimateInfo;
            }
            if (FormLinkInformation.TryFactory(obj.Water, out var WaterInfo))
            {
                yield return WaterInfo;
            }
            if (FormLinkInformation.TryFactory(obj.LODWater, out var LODWaterInfo))
            {
                yield return LODWaterInfo;
            }
            if (obj.Model is {} ModelItems)
            {
                foreach (var item in ModelItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            foreach (var item in obj.OrderedLandsTextures)
            {
                yield return FormLinkInformation.Factory(item);
            }
            if (FormLinkInformation.TryFactory(obj.Music, out var MusicInfo))
            {
                yield return MusicInfo;
            }
            if (obj.TopCell is {} TopCellItems)
            if (iterateNestedRecords)
            {
                foreach (var item in TopCellItems.EnumerateFormLinks(iterateNestedRecords))
                {
                    yield return item;
                }
            }
            foreach (var item in obj.SubCells.SelectMany(f => f.EnumerateFormLinks(iterateNestedRecords)))
            {
                yield return FormLinkInformation.Factory(item);
            }
            yield break;
        }
        
        public IEnumerable<IMajorRecordGetter> EnumerateMajorRecords(IWorldspaceGetter obj)
        {
            return EnumerateMajorRecordsLoopLogic(obj: obj);
        }
        
        public IEnumerable<IMajorRecordGetter> EnumerateMajorRecordsLoopLogic(IWorldspaceGetter obj)
        {
            if ((obj.TopCell != null))
            {
                if (obj.TopCell is {} TopCellitem)
                {
                    yield return TopCellitem;
                    foreach (var item in TopCellitem.EnumerateMajorRecords())
                    {
                        yield return item;
                    }
                }
            }
            foreach (var subItem in obj.SubCells)
            {
                foreach (var item in subItem.EnumerateMajorRecords())
                {
                    yield return item;
                }
            }
        }
        
        public IEnumerable<IMajorRecordGetter> EnumeratePotentiallyTypedMajorRecords(
            IWorldspaceGetter obj,
            Type? type,
            bool throwIfUnknown)
        {
            if (type == null) return WorldspaceCommon.Instance.EnumerateMajorRecords(obj);
            return WorldspaceCommon.Instance.EnumerateMajorRecords(obj, type, throwIfUnknown);
        }
        
        public IEnumerable<IMajorRecordGetter> EnumerateMajorRecords(
            IWorldspaceGetter obj,
            Type type,
            bool throwIfUnknown)
        {
            return EnumerateMajorRecordsLoopLogic(
                obj: obj,
                type: type,
                throwIfUnknown: throwIfUnknown);
        }
        
        public IEnumerable<IMajorRecordGetter> EnumerateMajorRecordsLoopLogic(
            IWorldspaceGetter obj,
            Type type,
            bool throwIfUnknown)
        {
            switch (type.Name)
            {
                case "IMajorRecord":
                case "MajorRecord":
                case "IFallout76MajorRecord":
                case "Fallout76MajorRecord":
                    if (!Worldspace_Registration.SetterType.IsAssignableFrom(obj.GetType())) yield break;
                    foreach (var item in this.EnumerateMajorRecordsLoopLogic(obj))
                    {
                        yield return item;
                    }
                    yield break;
                case "IMajorRecordGetter":
                case "IFallout76MajorRecordGetter":
                    foreach (var item in this.EnumerateMajorRecordsLoopLogic(obj))
                    {
                        yield return item;
                    }
                    yield break;
                case "Cell":
                case "ICellGetter":
                case "ICell":
                case "ICellInternal":
                    {
                        if (obj.TopCell is {} TopCellitem)
                        {
                            yield return TopCellitem;
                            foreach (var item in TopCellitem.EnumerateMajorRecords(type, throwIfUnknown: false))
                            {
                                yield return item;
                            }
                        }
                    }
                    foreach (var subItem in obj.SubCells)
                    {
                        foreach (var item in subItem.EnumerateMajorRecords(type, throwIfUnknown: false))
                        {
                            yield return item;
                        }
                    }
                    yield break;
                case "WorldspaceBlock":
                case "IWorldspaceBlockGetter":
                case "IWorldspaceBlock":
                    foreach (var subItem in obj.SubCells)
                    {
                        foreach (var item in subItem.EnumerateMajorRecords(type, throwIfUnknown: false))
                        {
                            yield return item;
                        }
                    }
                    yield break;
                case "Landscape":
                case "ILandscapeGetter":
                case "ILandscape":
                case "ILandscapeInternal":
                    {
                        if (obj.TopCell is {} LandscapeTopCellitem)
                        {
                            foreach (var item in LandscapeTopCellitem.EnumerateMajorRecords(type, throwIfUnknown: false))
                            {
                                yield return item;
                            }
                        }
                    }
                    foreach (var subItem in obj.SubCells)
                    {
                        foreach (var item in subItem.EnumerateMajorRecords(type, throwIfUnknown: false))
                        {
                            yield return item;
                        }
                    }
                    yield break;
                case "NavigationMesh":
                case "INavigationMeshGetter":
                case "INavigationMesh":
                case "INavigationMeshInternal":
                    {
                        if (obj.TopCell is {} NavigationMeshTopCellitem)
                        {
                            foreach (var item in NavigationMeshTopCellitem.EnumerateMajorRecords(type, throwIfUnknown: false))
                            {
                                yield return item;
                            }
                        }
                    }
                    foreach (var subItem in obj.SubCells)
                    {
                        foreach (var item in subItem.EnumerateMajorRecords(type, throwIfUnknown: false))
                        {
                            yield return item;
                        }
                    }
                    yield break;
                case "PlacedNpc":
                case "IPlacedNpcGetter":
                case "IPlacedNpc":
                case "IPlacedNpcInternal":
                    {
                        if (obj.TopCell is {} PlacedNpcTopCellitem)
                        {
                            foreach (var item in PlacedNpcTopCellitem.EnumerateMajorRecords(type, throwIfUnknown: false))
                            {
                                yield return item;
                            }
                        }
                    }
                    foreach (var subItem in obj.SubCells)
                    {
                        foreach (var item in subItem.EnumerateMajorRecords(type, throwIfUnknown: false))
                        {
                            yield return item;
                        }
                    }
                    yield break;
                case "PlacedObject":
                case "IPlacedObjectGetter":
                case "IPlacedObject":
                case "IPlacedObjectInternal":
                    {
                        if (obj.TopCell is {} PlacedObjectTopCellitem)
                        {
                            foreach (var item in PlacedObjectTopCellitem.EnumerateMajorRecords(type, throwIfUnknown: false))
                            {
                                yield return item;
                            }
                        }
                    }
                    foreach (var subItem in obj.SubCells)
                    {
                        foreach (var item in subItem.EnumerateMajorRecords(type, throwIfUnknown: false))
                        {
                            yield return item;
                        }
                    }
                    yield break;
                default:
                    if (InterfaceEnumerationHelper.TryEnumerateInterfaceRecordsFor(GameCategory.Fallout76, obj, type, out var linkInterfaces))
                    {
                        foreach (var item in linkInterfaces)
                        {
                            yield return item;
                        }
                        yield break;
                    }
                    if (throwIfUnknown)
                    {
                        throw new ArgumentException($"Unknown major record type: {type}");
                    }
                    else
                    {
                        yield break;
                    }
            }
        }
        
