        public void DeepCopyIn(
            IWorldspace item,
            IWorldspaceGetter rhs,
            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            base.DeepCopyIn(
                (IFallout76MajorRecord)item,
                (IFallout76MajorRecordGetter)rhs,
                errorMask,
                copyMask,
                deepCopy: deepCopy);
            if ((copyMask?.GetShouldTranslate((int)Worldspace_FieldIndex.EDID) ?? true))
            {
                item.EDID = rhs.EDID;
            }
            if ((copyMask?.GetShouldTranslate((int)Worldspace_FieldIndex.FULL) ?? true))
            {
                item.FULL = rhs.FULL?.DeepCopy();
            }
            if ((copyMask?.GetShouldTranslate((int)Worldspace_FieldIndex.LightingTemplate) ?? true))
            {
                item.LightingTemplate.SetTo(rhs.LightingTemplate.FormKeyNullable);
            }
            if ((copyMask?.GetShouldTranslate((int)Worldspace_FieldIndex.EncounterZone) ?? true))
            {
                item.EncounterZone.SetTo(rhs.EncounterZone.FormKeyNullable);
            }
